-- v28 second-pass expert-assisted contact sheet curation: a visual observation is not rights/technical approval.
-- All pages are copyrighted source pages; proposed course hints are NOT active associations.
on conflict(ref_id) do nothing;

-- For remaining uncurated items, register source-level screening only, not an individual visual semantic assertion.
create table if not exists public.training_integral_pdf_screening_v28(
  ref_id text primary key references public.training_integral_pdf_refs_v24(id) on delete cascade,
  screening_method text not null default 'contact_sheet_overview_and_source_class',
  triage_route text not null check(triage_route in('visual_detail_needed','clinical_expert_review','normative_expert_review','original_redraw_needed')),
  source_family text not null,
  source_course_hint text,
  screening_note text not null,
  screened_at timestamptz not null default now()
);
alter table public.training_integral_pdf_screening_v28 enable row level security;
revoke all on public.training_integral_pdf_screening_v28 from public,anon,authenticated;
grant select on public.training_integral_pdf_screening_v28 to authenticated;
create policy integral_pdf_screening_v28_admin_read on public.training_integral_pdf_screening_v28
  for select to authenticated using(private.is_platform_admin());
 ref_id,triage_route,source_family,source_course_hint,screening_note)
select r.id,
 case
  when r.category ilike '%soccorso%' then 'clinical_expert_review'
  when r.category ilike '%antincendio%' or r.category ilike '%DPI%' then 'normative_expert_review'
  when r.category ilike '%rischio meccanico%' then 'original_redraw_needed'
  when r.category ilike '%carrell%' or r.category ilike '%gru%' or r.category ilike '%terra%' or r.category ilike '%PLE%' or r.category ilike '%quota%' then 'original_redraw_needed'
  else 'visual_detail_needed'
 end,
 coalesce(r.category,'Fonte non classificata'),
 case when cardinality(r.candidate_course_keys)=1 then r.candidate_course_keys[1] else null end,
 'Screening preliminare su tavola composita da archivio originale e gruppo tematico della fonte; il soggetto di questa singola pagina non è ancora validato individualmente. Non effettuare pubblicazione, assegnazione o approvazione automatica.'
from public.training_integral_pdf_refs_v24 r
left join public.training_integral_pdf_visual_audit_v27 d on d.ref_id=r.id
where r.id>='pdf-50000' and d.ref_id is null
on conflict(ref_id) do nothing;

create table if not exists public.training_integral_pdf_comparison_v28(
 left_ref_id text not null,
 right_ref_id text not null,
 pixel_identical boolean not null default false,
 comparison_conclusion text not null check(comparison_conclusion in ('shared_template_different_topic','related_layout_different_content','shared_visual_component_different_page')),
 note text not null,
 compared_at timestamptz not null default now(),
 primary key(left_ref_id,right_ref_id),
 foreign key(left_ref_id,right_ref_id) references public.training_integral_pdf_similarity_v27(left_ref_id,right_ref_id) on delete cascade
);
alter table public.training_integral_pdf_comparison_v28 enable row level security;
revoke all on public.training_integral_pdf_comparison_v28 from public,anon,authenticated;
grant select on public.training_integral_pdf_comparison_v28 to authenticated;
create policy integral_pdf_comparison_v28_admin_read on public.training_integral_pdf_comparison_v28
  for select to authenticated using(private.is_platform_admin());
 left_ref_id,right_ref_id,pixel_identical,comparison_conclusion,note)
select p.left_ref_id,p.right_ref_id,false,
 case
  when p.left_ref_id='pdf-50587' and p.right_ref_id='pdf-50573' then 'shared_visual_component_different_page'
  when (p.left_ref_id between 'pdf-50178' and 'pdf-50293') and
       (p.right_ref_id between 'pdf-50178' and 'pdf-50293') then 'shared_template_different_topic'
  when (p.left_ref_id between 'pdf-50358' and 'pdf-50446') and
       (p.right_ref_id between 'pdf-50358' and 'pdf-50446') then 'shared_template_different_topic'
  else 'related_layout_different_content'
 end,
 'Confronto affiancato dei WebP originali: nessuna delle 57 coppie ha pixel identici. Sono riutilizzati elementi grafici, impaginazioni o alcuni schemi, ma non si tratta di duplicati tecnici da cancellare automaticamente.'
from public.training_integral_pdf_similarity_v27 p
on conflict(left_ref_id,right_ref_id) do nothing;
comment on table public.training_integral_pdf_screening_v28 is 'Per-asset first-pass source-based triage only; never count as individual visual technical review, copyright clearance or approval.';
comment on table public.training_integral_pdf_comparison_v28 is 'Human view of side-by-side source images; none pixel-identical; no deletion of similar but different slide content.';
